652	\begin{lemma}[Finite support of the order function]
653	  \label{lem:rationalMap_order_finite_support}
654	  \source{hartshorne-algebraic-geometry:page-0148}
655	  \lean{AlgebraicGeometry.rationalMap_order_finite_support}
656	  \leanok
657	  \uses{def:order_at_point}
658	
659	  Let \(X\) be a Noetherian integral scheme regular in codimension one.
660	  For every \(f\in K(X)\), the set
661	  \[
662	    \{Y\in X^{(1)}\mid\operatorname{ord}_Y(f)\neq0\}
663	  \]
664	  is finite.
665	\end{lemma}
666	\begin{proof}
667	  \leanok
668	  If \(f=0\), the support is empty by convention.  Otherwise choose a finite
669	  affine open cover \(X=\bigcup_i\operatorname{Spec}R_i\).  On one chart,
670	  write \(f=a/b\).  If the height-one prime \(\mathfrak p_Y\) contains
671	  neither \(a\) nor \(b\), both become units in
672	  \((R_i)_{\mathfrak p_Y}\), so \(\operatorname{ord}_Y(f)=0\).
673	  Hence every point of the support is a height-one prime containing \(a\)
674	  or \(b\).  Such a prime is minimal over \((a)\) or \((b)\), and a
675	  Noetherian ring has only finitely many minimal primes over an ideal.
676	  Taking the finite union over the cover proves the claim.
677	\end{proof}
678	
679	\begin{remark}
680	  \label{rem:finite_support_needs_noetherian}
681	  \uses{lem:rationalMap_order_finite_support}
682	  Global Noetherianness cannot be replaced by local Noetherianness.  The
683	  affine line with infinitely many origins is integral, locally Noetherian,
684	  and regular in codimension one, but its coordinate function has order one
685	  at every origin.  The scheme is not quasi-compact.
686	\end{remark}
