756	\section{Degree under finite morphisms}
757	
758	\begin{definition}[Pullback of a divisor along a finite morphism of curves]
759	  \label{def:finite_curve_divisor_pullback}
760	  \source{hartshorne-algebraic-geometry:page-0154}
761	
762	  Let \(\varphi\colon C\to D\) be a finite morphism of nonsingular curves
763	  over an algebraically closed field.
764	  For a closed point \(Q\in D\), choose a local parameter \(t\) at \(Q\) and
765	  set
766	  \[
767	    \varphi^*[Q]
768	      =\sum_{\varphi(P)=Q}\operatorname{ord}_P(t)\,[P].
769	  \]
770	  This is independent of the local parameter and extends linearly to
771	  \(\varphi^*\colon\operatorname{Div}(D)\to\operatorname{Div}(C)\).
772	\end{definition}
773	
774	\begin{theorem}[Degree of a finite pullback]
775	  \label{thm:finite_curve_degree_pullback}
776	  \source{hartshorne-algebraic-geometry:page-0155}
777	  \uses{def:finite_curve_divisor_pullback, def:divisor_degree}
778	
779	  If \(\varphi\colon C\to D\) is a finite morphism of complete nonsingular
780	  curves over an algebraically closed field and
781	  \(E\in\operatorname{Div}(D)\), then
782	  \[
783	    \deg(\varphi^*E)=\deg(\varphi)\deg(E).
784	  \]
785	\end{theorem}
786	\begin{proof}
787	  It suffices to take \(E=[Q]\).  On an affine neighbourhood
788	  \(\operatorname{Spec}B\) of \(Q\), let \(A\) be the integral closure of
789	  \(B\) in \(K(C)\), localize at \(Q\), and write the resulting finite
790	  torsion-free \(\mathcal O_{D,Q}\)-module as a free module of rank
791	  \([K(C):K(D)]=\deg(\varphi)\).  If \(t\) is a local parameter at \(Q\),
792	  the dimension of \(A/tA\) is this rank.  Decomposing \(A/tA\) at the
793	  points \(P\) over \(Q\) identifies the same dimension with
794	  \(\sum_{\varphi(P)=Q}\operatorname{ord}_P(t)\), which is
795	  \(\deg(\varphi^*[Q])\).
796	\end{proof}
