485	  \[
486	    [P]=
487	    \begin{cases}
488	      1\cdot\langle P,h\rangle,&
489	        \text{if }h:\operatorname{coheight}(P)=1,\\
490	      0,&\text{otherwise.}
491	    \end{cases}
492	  \]
