495	\begin{lemma}[Closed points of a nonsingular curve are prime divisors]
496	  \label{lem:curve_closed_point_prime_divisor}
497	  \source{hartshorne-algebraic-geometry:page-0154}
498	  \uses{def:divisor_closed_point}
499	
500	  Let \(C\) be a nonsingular integral curve over an algebraically closed
501	  field.  Every closed point \(P\in C\) has coheight one, and the divisor
502	  \([P]\) of \cref{def:divisor_closed_point} is the corresponding prime
503	  divisor with multiplicity one.
504	\end{lemma}
505	\begin{proof}
506	  A closed point of an integral curve is distinct from the generic point.
507	  Since the curve has dimension one, the specialization chain from the
508	  closed point to the generic point has length one.  Thus
509	  \(\operatorname{coheight}(P)=1\), and the positive branch of
510	  \cref{def:divisor_closed_point} gives the asserted divisor.
511	\end{proof}
