798	\begin{lemma}[A rational function gives a finite map to the projective line]
799	  \label{lem:rational_function_finite_map_to_p1}
800	  \source{hartshorne-algebraic-geometry:page-0155}
801	  \uses{def:finite_curve_divisor_pullback, def:principal_divisor}
802	
803	  Let \(C\) be a complete nonsingular curve over a field \(k\), and let
804	  \(f\in K(C)\setminus k\).  There is a finite morphism
805	  \(\varphi_f\colon C\to\mathbb P^1_k\) inducing the inclusion
806	  \(k(f)\subseteq K(C)\), and
807	  \[
808	    \operatorname{div}(f)
809	      =\varphi_f^*([0]-[\infty]).
810	  \]
811	\end{lemma}
812	\begin{proof}
813	  The rational function defines a morphism to \(\mathbb P^1\) because \(C\)
814	  is complete and nonsingular.  It is nonconstant, hence dominant; the
815	  induced extension \(K(C)/k(f)\) is finite, so the morphism is finite.
816	  At every closed point, the pullback multiplicity of \(0\) or \(\infty\)
817	  is respectively the order of the zero or the pole of \(f\).  Equality of
818	  all coefficients gives the divisor formula.
819	\end{proof}
