821	\begin{theorem}[Principal divisors have degree zero]
822	  \label{thm:principal_deg_zero}
823	  \source{hartshorne-algebraic-geometry:page-0155}
824	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal_degree_zero}
825	  \notready
826	  \uses{def:principal_divisor, def:divisor_degree}
827	
828	  Let \(C\) be a complete nonsingular curve over an algebraically closed
829	  field.  For every nonzero \(f\in K(C)\),
830	  \[
831	    \deg(\operatorname{div}(f))=0.
832	  \]
833	\end{theorem}
834	\begin{proof}
835	  \uses{lem:rational_function_finite_map_to_p1,
836	    thm:finite_curve_degree_pullback}
837	  If \(f\) is constant, its order at every point is zero.  Otherwise
838	  \cref{lem:rational_function_finite_map_to_p1} gives a finite morphism
839	  \(\varphi_f\colon C\to\mathbb P^1\) with
840	  \(\operatorname{div}(f)=\varphi_f^*([0]-[\infty])\).  Therefore
841	  \[
842	    \deg(\operatorname{div}(f))
843	      =\deg(\varphi_f)\deg([0]-[\infty])
844	      =\deg(\varphi_f)(1-1)=0
845	  \]
846	  by \cref{thm:finite_curve_degree_pullback}.
