179	[Point valuation and residue degree]
180	  \label{def:adelic_pointValuation}
181	  \lean{AlgebraicGeometry.Adelic.pointValuation}
182	  \uses{thm:adelic_chartRing_isDedekindDomain, def:order_at_point, lem:order_eq_order_restrict}
183	  % [scheidler] p. 24 (deg P = [F_P : K]); [cff] (C2) deg P = dim_K O_P/P
